import{_ as a,c as n,o as p,ag as e}from"./chunks/framework.BeChtK_P.js";const m=JSON.parse('{"title":"自建音乐库之Navidrome","description":"","frontmatter":{"title":"自建音乐库之Navidrome","author":"welpher.yu","date":"2024-06-21T15:47:11.000Z","tags":["音乐库","Navidrome"],"categories":["居家折腾"]},"headers":[],"relativePath":"posts/2024/music-service-self-hosted.md","filePath":"posts/2024/music-service-self-hosted.md"}'),i={name:"posts/2024/music-service-self-hosted.md"};function l(o,s,t,r,c,u){return p(),n("div",null,[...s[0]||(s[0]=[e(`<p>写在前：</p><blockquote><p>自己DIY了一台8盘位的All In One的NAS，后续又把光驱位安上了硬盘架，总共11盘位，用snapraid做了9+2的软raid。 主要用来备份照片，顺便搭建了影视库，音乐库等，影视库折腾了Jellyfin、Plex、Emby等，最后固定在Jellyfin。音乐库搭建了Logitech Media Server，在树莓派涨价之前买了两个树莓派+定制铝盒，用piCorePlayer系统，把一套退役电脑音箱和客厅电视音箱利用了起来，实现了数播串流。 LMS本身是支持网页端页面控制的，但是不是特别好用，又购买了iPeng这个软件来控制，为了手机上听LMS上面的音乐，又内购了iPeng的app播放功能。</p></blockquote><p>前面的数播在家里听音乐还是挺好的，不同的房间都可以布置一套piCorePlayer+音箱实现音乐自由，还支持手机推流到指定音箱。但是在手机上播放的功能却不是很友好，原本购买的iPeng可以通过家庭共享给家庭其他人使用，但app播放这个内购却不能共享。无意中发现了<a href="https://github.com/navidrome/navidrome" target="_blank" rel="noreferrer">Navidrome</a>，这个项目是一个开源的音乐服务器，可以很方便的搭建一个音乐服务，并且可以很方便的使用手机app播放音乐。</p><h3 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h3><p>通过docker-compose很方便的就可以把服务部署好了。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>version: &quot;3&quot;</span></span>
<span class="line"><span>services:</span></span>
<span class="line"><span>  navidrome:</span></span>
<span class="line"><span>    image: deluan/navidrome:latest</span></span>
<span class="line"><span>    ports:</span></span>
<span class="line"><span>      - &quot;4533:4533&quot;   # 左边可以改成自己服务器未被占用的端口</span></span>
<span class="line"><span>    environment:</span></span>
<span class="line"><span>      # Optional: put your config options customization here. Examples(这些都是可选的):</span></span>
<span class="line"><span>      ND_SCANSCHEDULE: 1m</span></span>
<span class="line"><span>      # lastfm配置</span></span>
<span class="line"><span>      ND_LASTFM_ENABLED:   # 设置 false 为完全禁用 Last.fm 集成</span></span>
<span class="line"><span>      ND_LASTFM_APIKEY: apikey # 修改成自己的APIKEY</span></span>
<span class="line"><span>      ND_LASTFM_SECRET: SECRET  # 修改成自己的SECRET</span></span>
<span class="line"><span>      ND_LASTFM_LANGUAGE: zh  # 用于从 Last.fm 检索的语言的两个字母代码，简体中文为 zh</span></span>
<span class="line"><span>      # Spotify配置</span></span>
<span class="line"><span>      ND_SPOTIFY_ID: spotifyId  # 修改成自己的ID</span></span>
<span class="line"><span>      ND_SPOTIFY_SECRET: spotifySecret  # 修改成自己的SECRET</span></span>
<span class="line"><span>      </span></span>
<span class="line"><span>      ND_LOGLEVEL: info</span></span>
<span class="line"><span>      ND_SESSIONTIMEOUT: 24h</span></span>
<span class="line"><span>      ND_BASEURL: &quot;&quot;</span></span>
<span class="line"><span>      # 转码设置</span></span>
<span class="line"><span>      ND_ENABLETRANSCODINGCONFIG: &quot;true&quot; #  设置为 true 才能支持转码功能</span></span>
<span class="line"><span>      ND_TRANSCODINGCACHESIZE: &quot;4000M&quot; #转码缓存的大小。设置 0 为禁用缓存，默认为 100MB</span></span>
<span class="line"><span>      ND_IMAGECACHESIZE: &quot;1000M&quot; #图片缓存的大小。设置 0 为禁用缓存，默认为 100MB</span></span>
<span class="line"><span>    volumes:</span></span>
<span class="line"><span>      - &quot;./data:/data&quot;</span></span>
<span class="line"><span>      - &quot;/your music path/music:/music:ro&quot;  # 冒号左边修改成自己本地的音乐文件夹路径</span></span>
<span class="line"><span>  miniserve:</span></span>
<span class="line"><span>    image: svenstaro/miniserve:latest</span></span>
<span class="line"><span>    depends_on:</span></span>
<span class="line"><span>      - navidrome</span></span>
<span class="line"><span>    ports:</span></span>
<span class="line"><span>      - &quot;4534:8080&quot;</span></span>
<span class="line"><span>    volumes:</span></span>
<span class="line"><span>      - &quot;/your music path/music:/downloads&quot;  # 冒号左边修改成自己本地的音乐文件夹路径</span></span>
<span class="line"><span>    command: &quot;-r -z -u -q -p 8080 -a username:password /downloads&quot;  # 修改成自己的账号:密码</span></span>
<span class="line"><span>    restart: unless-stopped</span></span></code></pre></div><h3 id="navidrome客户端" tabindex="-1">Navidrome客户端 <a class="header-anchor" href="#navidrome客户端" aria-label="Permalink to &quot;Navidrome客户端&quot;">​</a></h3><p>iOS: play:Sub, substreamer, Amperfy 和 iSub</p><p>Android: DSub, Subtracks, substreamer, Ultrasonic 和 Audinaut</p><p>Web: Subplayer, Airsonic Refix, Aurial, Jamstash 和 Subfire</p><p>Desktop: Sublime Music (Linux) 和 Sonixd (Windows/Linux/macOS)，Supersonic</p><p>CLI: Jellycli (Windows/Linux) 和 STMP (Linux/macOS)</p><p>Connected Speakers: Sonos: bonob</p><p>Alexa: AskSonic</p><p>Other: Subsonic Kodi Plugin Navidrome Kodi Plugin</p>`,15)])])}const S=a(i,[["render",l]]);export{m as __pageData,S as default};
